typeSystemExample.source:
func maxOf<T: Comparable>(_ a: T, _ b: T) -> T {
    a >= b ? a : b
}

print(maxOf(3, 7))
print(maxOf(1.5, 2.8))

concurrencyExample.source:
import Foundation

@main
struct App {
    static func main() async {
        let results = await withTaskGroup(of: Int.self) { group in
            for i in 0..<4 {
                group.addTask { i * i }
            }
            var r: [Int] = []
            for await v in group { r.append(v) }
            return r
        }
        print(results.map(String.init).joined(separator: " "))
    }
}
